import{useEffect,useMemo,useState}from"react";import type{RouteConfig}from"@mercurjs/dashboard-sdk";import"../../spike/vendor-spike.css";declare const __BACKEND_URL__:string
export const config:RouteConfig={label:"الخصومات والكوبونات",rank:60};
type Product={id:string;title:string;variants?:any[]};type Offer={id:string;prices?:any[];product_variant?:any};
const base=()=>String(__BACKEND_URL__||"http://localhost:9000").replace(/\/$/,"");async function api(p:string,i?:RequestInit){const r=await fetch(base()+p,{credentials:"include",...i,headers:{...(i?.body?{"content-type":"application/json"}:{}),...(i?.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||`HTTP ${r.status}`);return d}
export default function Page(){const[products,setProducts]=useState<Product[]>([]),[offers,setOffers]=useState<Offer[]>([]),[rows,setRows]=useState<any[]>([]),[productId,setProductId]=useState(""),[discount,setDiscount]=useState(""),[code,setCode]=useState(""),[percent,setPercent]=useState("10"),[scope,setScope]=useState<"product"|"store">("product"),[couponProduct,setCouponProduct]=useState(""),[msg,setMsg]=useState("");
const load=async()=>{const[p,o,d]=await Promise.all([api('/vendor/products?limit=200&fields=id,title,*variants'),api('/vendor/offers?limit=300&fields=id,*prices,*product_variant.product'),api('/vendor/spike/discounts')]);setProducts(p.products||[]);setOffers(o.offers||[]);setRows(d.discounts||[])};useEffect(()=>{load().catch(e=>setMsg(e.message))},[]);
const product=products.find(x=>x.id===productId);const offer=useMemo(()=>offers.find((o:any)=>o.product_variant?.product?.id===productId)||offers.find((o:any)=>product?.variants?.some(v=>v.id===o.product_variant?.id)),[offers,productId,product]);const price=Number(offer?.prices?.[0]?.amount||0),currency=String(offer?.prices?.[0]?.currency_code||'SAR').toUpperCase(),amount=Math.max(0,Number(discount)||0),after=Math.max(0,price-amount),pct=price>0?Math.round(amount/price*100):0;
const sendDiscount=async()=>{if(!product||!offer||!price)return setMsg('اختر منتجًا له سعر فعال');if(amount<=0||amount>=price)return setMsg('قيمة الخصم يجب أن تكون أكبر من صفر وأقل من السعر');await api('/vendor/spike/discounts',{method:'POST',body:JSON.stringify({offer_id:offer.id,product_id:product.id,product_title:product.title,original_price:price,discounted_price:after,currency_code:currency})});setDiscount('');setProductId('');setMsg('تم إرسال الخصم للأدمن للموافقة');load()};
const sendCoupon=async()=>{if(!code.trim())return setMsg('اكتب كود الكوبون');if(scope==='product'&&!couponProduct)return setMsg('اختر المنتج');await api('/vendor/spike/discounts',{method:'POST',body:JSON.stringify({request_type:'coupon',coupon_code:code,coupon_percentage:Number(percent),target_type:scope,target_id:scope==='store'?'':couponProduct,product_title:scope==='store'?'كامل المتجر':products.find(p=>p.id===couponProduct)?.title})});setCode('');setCouponProduct('');setMsg('تم إرسال الكوبون للأدمن للموافقة');load()};
return <div className="spike-page" dir="rtl"><div className="spike-card"><h1 className="spike-title">الخصومات والكوبونات</h1>{msg&&<div className="spike-review-hint">{msg}</div>}<h2>خصم منتج</h2><div className="spike-vendor-grid"><label>المنتج<select value={productId} onChange={e=>{setProductId(e.target.value);setDiscount('')}}><option value="">اختر المنتج</option>{products.map(p=><option key={p.id} value={p.id}>{p.title}</option>)}</select></label><label>السعر الأصلي<input readOnly value={price?`${price} ${currency}`:''}/></label><label>قيمة الخصم<input type="number" min="0" value={discount} onChange={e=>setDiscount(e.target.value)} placeholder="مثال: 20"/></label><label>السعر بعد الخصم<input readOnly value={price?`${after} ${currency}`:''}/></label></div><div className="spike-toolbar"><button className="spike-btn" onClick={sendDiscount}>إرسال للموافقة</button><b>{pct>0?`≈ ${pct}%`:''}</b></div>
<h2 style={{marginTop:28}}>كوبون</h2><div className="spike-vendor-grid"><label>الكود<input value={code} onChange={e=>setCode(e.target.value.toUpperCase())}/></label><label>النسبة %<input type="number" min="1" max="99" value={percent} onChange={e=>setPercent(e.target.value)}/></label><label>يطبق على<select value={scope} onChange={e=>setScope(e.target.value as any)}><option value="product">منتج محدد</option><option value="store">كامل المتجر</option></select></label>{scope==='product'&&<label>المنتج<select value={couponProduct} onChange={e=>setCouponProduct(e.target.value)}><option value="">اختر</option>{products.map(p=><option key={p.id} value={p.id}>{p.title}</option>)}</select></label>}</div><button className="spike-btn" onClick={sendCoupon}>إرسال الكوبون للموافقة</button>
<h2 style={{marginTop:28}}>الطلبات السابقة</h2><table className="spike-table"><thead><tr><th>النوع</th><th>المنتج/الكود</th><th>القيمة</th><th>الحالة</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td>{r.request_type==='coupon'?'كوبون':'خصم'}</td><td>{r.coupon_code||r.product_title}</td><td>{r.request_type==='coupon'?`${r.coupon_percentage}%`:`${r.percentage}%`}</td><td>{r.status==='pending'?'بانتظار الموافقة':r.status==='approved'?'مقبول':'مرفوض'}</td></tr>)}</tbody></table></div></div>}
